import json
def solve(g):
    import itertools
    H,W=len(g),len(g[0])
    # find rectangles: colors forming closed rings; treat any color!=0 as candidate
    used=[[False]*W for _ in range(H)]
    boxes=[]
    seen=set()
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v!=0 and (r,c) not in seen:
                # BFS boundary of this color component
                comp=[]; q=[(r,c)]; seen.add((r,c)); 
                while q:
                    a,b=q.pop(); comp.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and g[na][nb]==v and (na,nb) not in seen:
                            seen.add((na,nb)); q.append((na,nb))
                # bounding box
                rs=[a for a,b in comp]; cs=[b for a,b in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                # check it's a ring: all border cells are v and interior has no v
                ok=all(g[r][c]==v for r in range(r0,r1+1) for c in (c0,c1)) \
                     and all(g[r][c]==v for c in range(c0,c1+1) for r in (r0,r1)) \
                     and all(g[r][c]!=v for r in range(r0+1,r1) for c in range(c0+1,c1))
                if ok and len(comp)>=4: boxes.append((v,r0,r1,c0,c1))
    out=[row[:] for row in g]
    # scatter colors: colors with count small appearing isolated; rank by total count
    cnt={}
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0: cnt[g[r][c]]+=1
    boxvs=[v for v,_,_,_,_ in boxes]
    sc=[v for v in cnt if v not in boxvs]
    sc.sort(key=lambda v:cnt[v], reverse=True)  # most frequent first
    boxes.sort(key=lambda b:(b[1]*(b[2]-b[1]+1))*(b[3]*(b[4]-b[3]+1)), reverse=True)
    assign=[sc[i%len(sc)] for i in range(len(boxes))]
    for (v,r0,r1,c0,c1),col in zip(boxes,assign):
        tpar=(r0+c0)%2
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if (r+c)%2==tpar: out[r][c]=col
    # clear scattered noise: keep only boxes and their fills -> zeros elsewhere
    for r in range(H):
        for c in range(W):
            if out[r][c]==0: continue
            # is this part of a box ring or fill? check belongs to some box
            found=False
            for vv,a0,b0,c0d,d0 in boxes:
                if vv==out[r][c] and a0<=r<=b0 and c0d<=c<=d0:
                    # ring cell: on border
                    onborder = (r in(a0,b0)) or (c in(c0d,d0))
                    if onborder or True: pass
                    found=True; break
            # simpler: zero everything not on any box border / interior-fill already set... interior fills are set above from original zeros
    # revert: keep only cells that are box borders or were set as fills
    for r in range(H):
        for c in range(W):
            val=out[r][c]
            if val!=0:
                kept=False
                for vv,a0,b0,c0d,d0 in boxes:
                    if val==vv and (r in(a0,b0) and c0d<=c<=d0) or (val!=vv and a0<r<b0 and c0d<c<d0 and val in sc):
                        kept=True; break
                if not kept: out[r][c]=0
    return out
