        inner=all(g[a][b]!=v for a in range(rr[0]+1,rr[1]) for b in range(cc[0]+1,cc[1]))
        return border_ok and inner
    # connected components of nonzero cells
    comps=[]
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v!=0 and not seen[r][c]:
                seen[r][c]=True; q=[(r,c)]
                while q:
                    a,b=q.pop()
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and g[na][nb]==v and not seen[na][nb]:
                            seen[na][nb]=True; q.append((na,nb))
                rs=[a for a,b in q]; cs=[b for a,b in q]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                if is_ring(v,(r0,r1),(c0,c1)):
                    area=(r1-r0+1)*(c1-c0+1)
                    comps.append((v,r0,r1,c0,c1,area))
    cnt=defaultdict(int)
    for v in range(10):
        for r in range(H):
            for c in range(W):
                if g[r][c]==v: cnt[v]+=1
    boxvs={v for v,_,_,_,_,_ in comps}
    noise=sorted([v for v in cnt if v not in boxvs], key=lambda v:-cnt[v])
    comps.sort(key=lambda b:(-b[5]), reverse=False)  # largest first
    out=[row[:] for row in g]
    for i,(v,r0,r1,c0,c1,_) in enumerate(comps):
        col=noise[i%len(noise)]
        tp=(r0+c0)%2
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if (r+c)%2==tp: out[r][c]=col
