from collections import defaultdict
def solve(g, noise_order='asc'):
    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]
    def ring_ok(v,r0,r1,c0,c1):
        if r1-r0<2 or c1-c0<2: return False
        if not all(g[a][b]==v for a in range(r0,r1+1) for b in (c0,c1)): return False
        if not all(g[a][b]==v for a in (r0,r1) for b in range(c0,c1+1)): return False
        if any(g[a][b]==v for a in range(r0+1,r1) for b in range(c0+1,c1)): return False
        return True
    boxes=[]
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v!=0 and not seen[r][c]:
                seen[r][c]=True; q=[(r,c)]; comp=[]
                while q:
                    a,b=q.pop(); comp.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and g[na][nb]==v and not seen[na][nb]:
                            seen[na][nb]=True; q.append((na,nb))
                rs=[a for a,b in comp]; cs=[b for a,b in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                if len(comp)>=4 and ring_ok(v,r0,r1,c0,c1):
                    boxes.append((v,r0,r1,c0,c1))
    cnt=defaultdict(int)
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0: cnt[g[r][c]]+=1
    boxvs={v for v,_,_,_,_ in boxes}
    noise=sorted([v for v in cnt if v not in boxvs], key=lambda v:cnt[v], reverse=(noise_order=='desc'))
    out=[[0]*W for _ in range(H)]
    for i,(v,r0,r1,c0,c1) in enumerate(boxes):
        col=noise[i%len(noise)]
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if (r+c)%2==(r0+c0)%2: out[r][c]=col
    # clear stray noise outside boxes
    for r in range(H):
        for c in range(W):
            if out[r][c]==0: continue
            inside=False
            for v,r0,r1,c0,c1 in boxes:
                if r0<r<r1 and c0<c<c1: inside=True
            if not inside: out[r][c]=0
    return out
for order in ['asc','desc']:
    ok=all(solve(G[k+' input'],order)==G[k+' output'] for k in ['Demo pair 1','Demo pair 2'])
    print(order,'MATCH' if ok else 'FAIL')
