def solve(g, order='asc'):
    H,W=len(g),len(g[0])
    cnt=defaultdict(int)
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0: cnt[g[r][c]]+=1
    rng=rings(g); noise=[v for v,*_,_ in [(x['v'],x['T'],x['B'],x['L'],x['R'],x['A']) for x in rng]]
    noise=sorted([v for v in cnt if v not in {b['v'] for b in rng}], key=lambda v:cnt[v])
    out=[[0]*W for _ in range(H)]
    for i,b in enumerate(rng):
        col=noise[i%len(noise)]
        for r in range(b['T']+1,b['B']):
            for c in range(b['L']+1,b['R']):
                if (r+c)%2==(b['T']+b['L'])%2: out[r][c]=col
    return out
