    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
from collections import defaultdict
def analyze(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; res=[]; cnt=defaultdict(int)
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0: cnt[g[r][c]]+=1
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v!=0 and not seen[r][c]:
                seen[r][c]=True; comp=[(r,c)]
                stack=[(r,c)]
                while stack:
                    a,b=stack.pop()
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and g[na][nb]==v and not seen[na][nb]:
                            seen[na][nb]=True; stack.append((na,nb)); comp.append((na,nb))
                rs=[a for a,b in comp]; cs=[b for a,b in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                ok=(r1-r0>=2 and c1-c0>=2 and all(g[a][b]==v for a in range(r0,r1+1) for b in (c0,c1))
                      and all(g[a][b]==v for a in (r0,r1) for b in range(c0,c1+1))
                      and not any(g[a][b]==v for a in range(r0+1,r1) for b in range(c0+1,c1)))
                if ok: res.append({'v':v,'T':r0,'B':r1,'L':c0,'R':c1,'A':(r1-r0-1)*(c1-c0-1)})
    return sorted(res,key=lambda b:(b['A'],b['T']+b['L'])), dict(cnt)
def f(g):
    rng_,cnt=analyze(g)
    noise=[v for v in cnt if v not in {b['v'] for b in rng_}]
    noise.sort(key=lambda v:cnt[v])   # rarest first -> smallest box
    out=[row[:] for row in g]
    for i,b in enumerate(rng_):
        col=noise[i]
        for r in range(b['T']+1,b['B']):
            for c in range(b['L']+1,b['R']):
                if out[r][c]==0 and (r+c)%2==(b['T']+b['L'])%2: out[r][c]=col
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]!=0 and not any(b['T']<=r<=b['B'] and b['L']<=c<=b['R'] for b in rng_):
                out[r][c]=0
    return out
for k in ['Demo pair 1','Demo pair 2']:
    print(k, f(G[k+' input'])==G[k+' output'])
print(json.dumps(f(G['Test input'])))
